VALUES (NULL, NULL, 2539, 'Alpha Protocol', 'Alpha Protocol', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25mo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arh18.jpg', 'A talented young agent cast out by his government, Thorton is the only one with the information needed to stop an impending international catastrophe. To do so means he must cut himself off from the very people he is sworn to protect. As players determine how to accomplish different objectives, the decisions made and actions taken in each mission will ultimately transform the type of secret agent Michael Thorton will become. Every choice the player makes as Michael Thorton will carry consequences for his future and the fate of the world.', 'https://www.igdb.com/games/alpha-protocol', '["OnLive Game System", "PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.7, 0, 6.26, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
