VALUES (NULL, NULL, 2112, 'Mirror''s Edge Catalyst', 'Mirror''s Edge Catalyst', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28r2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4nh.jpg', 'Mirror''s Edge Catalyst is an action-adventure game and the reboot to Mirror''s Edge. The story in the game explores the past of the protagonist Faith. Like in the previous game, the main gameplay in Mirror''s Edge Catalyst involves traversing the city using parkour to reach certain objectives. Unlike the linear levels in Mirror''s Edge, Mirror''s Edge Catalyst features an open-world free-roaming environment. Combat has been overhauled and emphasized compared to the first game and Catalyst no longer allows the player to use weapons, instead focusing on melee attacks.', 'https://www.igdb.com/games/mirrors-edge-catalyst', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 6.9, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
