VALUES (NULL, NULL, 41, 'Deus Ex', 'Deus Ex', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocc3x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dghbu1marmlar4qhh9nv.jpg', 'A philosophical first-person WRPG set in a dystopian 2052 in which JC Denton, a nano-augmented agent for the anti-terrorist organization UNATCO, is tasked with stopping the invasion of Liberty Island by the terrorist group NSF. As events unfold, Denton finds that he plays a large part in a world-spanning conspiracy which forces him to ponder his allegiances, beliefs, morality, and view of right and wrong.', 'https://www.igdb.com/games/deus-ex', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.8, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
