VALUES (NULL, NULL, 5551, 'Nidhogg', 'Nidhogg', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1n39.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/are5u.jpg', 'Nidhogg is the award-winning fencing tug-of-war, full of graceful acrobatics and clumsy stabs. This is the ultimate two-player showdown of fast-paced fencing and melee attacks. Beware, advantages in Nidhogg are often fleeting, as new opponents continually spawn in your way. Use a variety of fencing maneuvers while armed -- lunges, parries, and even dirty tricks like throwing your sword. If swordless, press forward with punches, sweep kicks, dive kicks, rolls, and wall jumps.', 'https://www.igdb.com/games/nidhogg', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "PlayStation Vita"]', NULL, 8.0, 0, 2.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
