VALUES (NULL, NULL, 139472, 'Hellish Quart', 'Hellish Quart', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ju7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aro2x.jpg', 'A fighting game about sword dueling, in which the blades really clash using physics, and the characters use motion captured fencing techniques. Play as one of many 17th century warriors and use sabers, rapiers, broadswords and many other blades in single player campaign, arcade, or local multiplayer with friends.', 'https://www.igdb.com/games/hellish-quart', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 2.05, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
