VALUES (NULL, NULL, 287791, 'Legends of the Round Table', 'Legends of the Round Table', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9p2w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2rgt.jpg', 'Lead the Knights of the Round Table through King Arthur''s legend in a unique RPG, full of honor, magic and romance. Plunge into a colorful world inspired by medieval art, tales and music. Undertake perilous quests and fiercely defend your kingdom to make the flower of chivalry blossom again.', 'https://www.igdb.com/games/legends-of-the-round-table', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
