VALUES (NULL, NULL, 225590, 'Your Only Move is Hustle', 'Your Only Move is Hustle', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ftc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23hm.jpg', 'Your Only Move Is Hustle is an online, turn-based fighting game and superpowered fight scene simulator. Using a unique and accessible control scheme, harness the power of precognition to land the perfect blow. Master your technique, execute flashy combos, and outsmart opponents across the world, frame-by-frame.', 'https://www.igdb.com/games/your-only-move-is-hustle', '["Linux", "PC (Microsoft Windows)"]', NULL, 7.2, 0, 2.015, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
