VALUES (NULL, NULL, 238782, 'Felvidek', 'Felvidek', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8aiu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar273f.jpg', 'Find out what unlikely events take place in this alternate history region of Slovak Highlands. This land is ravaged by Hussite pillagers and Ottoman spies while surreal horrors dwell in the dark. It''s now up to Pavol, a fair knight with alcohol problems, to gather a party and stop those who oppose our kingdom.', 'https://www.igdb.com/games/felvidek', '["PC (Microsoft Windows)"]', NULL, 9.0, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
