VALUES (NULL, NULL, 34409, 'Endless Sky', 'Endless Sky', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hqf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardu4.jpg', 'Endless Sky is an open source 2D space trading and combat game inspired by the classic Escape Velocity series. Work your way up from a relatively wimpy shuttle, cargo ship, or fighter, to a highly upgraded and customized flagship or to a massive fleet of warships or freighters.', 'https://www.igdb.com/games/endless-sky', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.6, 0, 1.08, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
