VALUES (NULL, NULL, 22, 'System Shock 2', 'System Shock 2', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bak.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6z3.jpg', 'A first-person cyberpunk exploratory horror RPG and sequel to System Shock (1994) in which a soldier wakes up in the starship Von Braun in the aftermath of a disaster and finds himself in the midst of a conflict between SHODAN, the artificial intelligence antagonist of System Shock seeking mastery over humanity, and The Many, a flesh-based psychic hive mind led by the ship''s corrupted AI.', 'https://www.igdb.com/games/system-shock-2', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.9, 0, 4.0475, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
