VALUES (NULL, NULL, 18375, 'System Shock', 'System Shock', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ik8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4rb.jpg', 'After 22 years, cyberpunk cult classic System Shock is getting an update. A "reimagined" version of the 1994 Windows PC game is in the works at Night Dive Studios for PC and Xbox One, and it''s a project that company founder Stephen Kick says he can hardly believe is really happening.', 'https://www.igdb.com/games/system-shock--1', '["Xbox Series X|S", "PlayStation 4", "Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 1.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
