VALUES (NULL, NULL, 19686, 'Resident Evil 2', 'Resident Evil 2', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ir3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4owg.jpg', 'Resident Evil 2 is a remake of 1998''s Resident Evil 2. The game was not developed with the intent of improving the original, but rather a reimagining of the original story with redesigned maps, characters and story elements. Gameplay mechanics are more similar to Resident Evil 7: Biohazard though with the use of an over-the-shoulder camera.', 'https://www.igdb.com/games/resident-evil-2--1', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One"]', NULL, 9.0, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
