VALUES (NULL, NULL, 36476, 'Hellpoint', 'Hellpoint', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bwn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar71i.jpg', 'Hellpoint is a dark sci fi action RPG set in the aftermath of a massive quantum cataclysm. Every living being quickly lost their mind as their memories and bodies were merged with alternate versions of themselves from parallel universes. The accident also attracted entities of immense power that should have been left alone, in the depth of other dimensions.', 'https://www.igdb.com/games/hellpoint', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
