VALUES (NULL, NULL, 159119, 'Dead Space', 'Dead Space', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkv5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxuo.jpg', 'The sci-fi survival-horror classic Dead Space returns, completely rebuilt from the ground up to offer a deeper, more immersive experience. This remake brings jaw-dropping visual fidelity, suspenseful atmospheric audio, and improvements to gameplay while staying faithful to the original game’s thrilling vision.', 'https://www.igdb.com/games/dead-space--1', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.7, 0, 1.09, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
