VALUES (NULL, NULL, 2, 'Thief: The Dark Project', 'Thief: The Dark Project', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22ne.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2mqz.jpg', 'Thief is a first-person stealth game that likes the dark. You sneak through the ruins of haunted cathedrals, subterranean ruins, and forbidding prisons, in a dark and sinister city - heavily inspired by Steampunk and the Dark Ages. Garrett finds an ally in the shadows, as he steals for money and uncovers the hidden agendas of allies and enemies. The story that unravels is one of deception and revenge.', 'https://www.igdb.com/games/thief-the-dark-project', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 9.21, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
