VALUES (NULL, NULL, 1, 'Thief II: The Metal Age', 'Thief II: The Metal Age', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co698n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar67a1.jpg', 'The ultimate thief is back! Tread softly as you make your way through 15 new complex, non-linear levels full of loot to steal and guards to outsmart. Improved enemy AI, new gadgets and a riveting story will draw you into the world of Thief II: The Metal Age, a place of powerful new technologies, fanatical religions and corruption.', 'https://www.igdb.com/games/thief-ii-the-metal-age', '["PC (Microsoft Windows)"]', NULL, 8.8, 0, 9.21, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
