VALUES (NULL, NULL, 385145, 'SeverLink', 'SeverLink', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9sf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5fyk.jpg', 'SeverLink is a retro stealth action, inspired by the console classics of the early 2000s like Splinter Cell, MGS2-3 and Hitman Contracts. With the art direction emulating the distinct look of the Playstation 2 library of games.', 'https://www.igdb.com/games/severlink', '["Linux", "PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
