VALUES (NULL, NULL, 76164, 'Marvel Strike Force', 'Marvel Strike Force', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qnj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ott.jpg', 'In Marvel Strike Force, ready for battle alongside allies and arch-rivals in this action-packed, visually-stunning free-to-play game for your phone or tablet. An assault on Earth has begun and Super Heroes and Super Villains are working together to defend it! Lead the charge by assembling your ultimate squad, including Spider-Man, Doctor Strange, Groot, Rocket Raccoon, Loki, Venom, Elektra, Captain America and Iron Man, as you enter strategic combat against an all-new enemy threat. It’s time to fight! Gather your squad and prepare for the battle to save Earth!', 'https://www.igdb.com/games/marvel-strike-force', '["Web browser", "Android", "iOS"]', NULL, 7.6, 0, 0.0, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
