VALUES (NULL, NULL, 103298, 'Doom Eternal', 'Doom Eternal', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3p5n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4do.jpg', 'Doom Eternal is a first-person shooter developed by id Software and the sequel to Doom (2016). Players control the Doom Slayer as he fights to end a demonic invasion of Earth. Combat is built around aggressive resource management, where health, armor, and ammo are gained by executing, igniting, or chainsawing enemies. The game introduces platforming segments, destructible enemy weak points, an expanded weapon arsenal, and a multiplayer mode called Battlemode, where one player-controlled Slayer fights two player-controlled demons.', 'https://www.igdb.com/games/doom-eternal', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.5, 0, 5.09500000000000063e+00, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
