VALUES (NULL, NULL, 208417, 'Ravenswatch', 'Ravenswatch', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocs4b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6gbk.jpg', 'Fallen heroes of old folk tales and legends: you are on the verge of a crucial battle against the Nightmare invading and corrupting your world. A roguelike action game from the creators of Curse of the Dead Gods, playable solo or in online co-op.', 'https://www.igdb.com/games/ravenswatch', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.9, 0, 8.52, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
