VALUES (NULL, NULL, 19935, 'Wizard of Legend', 'Wizard of Legend', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27gi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8k1.jpg', '"Wizard of Legend is a fast paced 2D dungeon crawler where you assume the role of a powerful wizard on his quest for fame and glory! Combine powerful spells and quick reflexes to overcome all of the challenges and become a Wizard of Legend!"

"Battle your way through each challenge by defeating powerful conjured enemies! Collect valuable spells and relics and build up your magical arsenal to fit your playstyle! Achieve mastery over magic by chaining spells together to create devastating combination attacks! Face each council member in combat and earn your right to become a Wizard of Legend!"', 'https://www.igdb.com/games/wizard-of-legend', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.3, 0, 8.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
