VALUES (NULL, NULL, 8173, 'Overwatch', 'Overwatch', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rcb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/un1ngd2k0nv9uubxx04f.jpg', 'Join the fight for the future in the world of Overwatch and choose your hero from a diverse cast of soldiers, scientists, adventurers, and oddities. Bend time, defy physics, and unleash a dizzying array of extraordinary powers and weapons. Engage your enemies in iconic locations from around the globe in the ultimate team-based shooter.', 'https://www.igdb.com/games/overwatch', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.5, 0, 6.52, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
