VALUES (NULL, NULL, 25657, 'Destiny 2', 'Destiny 2', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc89g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6gei.jpg', 'Dive into the world of Destiny 2 to explore the mysteries of the solar system and experience responsive first-person shooter combat. Unlock powerful elemental abilities and collect unique gear to customize your Guardian''s look and playstyle. Enjoy Destiny 2’s cinematic story, challenging co-op missions, and a variety of PvP modes alone or with friends. Download for free today and write your legend in the stars.', 'https://www.igdb.com/games/destiny-2', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.8, 0, 10.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
