VALUES (NULL, NULL, 3968, 'Dragon''s Dogma', 'Dragon''s Dogma', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zm7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dy4bsecybyozo7hsd6p8.jpg', 'Set in a huge open world, Dragon’s Dogma: Dark Arisen presents a rewarding action combat experience. Players embark on an epic adventure in a rich, living world with three AI companions, known as Pawns. These partners fight independently, demonstrating prowess and ability that they have developed based on traits learnt from each player. PC users can share these Pawns online and reap rewards of treasure, tips and strategy hints for taking down the terrifying enemies. Pawns can also be borrowed when specific skills are needed to complete various challenging quests.', 'https://www.igdb.com/games/dragon-s-dogma', '["PlayStation 3", "Xbox 360"]', NULL, 7.5, 0, 7.846, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
