VALUES (NULL, NULL, 324575, 'Tombwater', 'Tombwater', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/codbyg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ftq.jpg', 'Explore the accursed Wild West town of Tombwater and lay bare the eldritch horrors that lie beneath. Survive blood-spilling combat in this gruesome 2D action-RPG that might just drive you to madness.', 'https://www.igdb.com/games/tombwater', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
