VALUES (NULL, NULL, 27687, 'Cloud Pirates', 'Cloud Pirates', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wuh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar14q9.jpg', 'Cloud Pirates is an action MMO in which you fire your cannons to crush the enemy in fast-paced aerial battles! Take command of your own pirate airship, equip it with cutting edge weaponry and blast your enemies from the skies. Unlock and upgrade more than 25 ships and battle in 4 exciting game modes.', 'https://www.igdb.com/games/cloud-pirates', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 0.0, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
