VALUES (NULL, NULL, 134710, 'Grand Theft Auto Online', 'Grand Theft Auto Online', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4rq1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4phw.jpg', 'Grand Theft Auto Online is an online multiplayer action-adventure game, and is a standalone version of Grand Theft Auto V. Set within the fictional state of San Andreas (based on Southern California), Grand Theft Auto Online allows up to 30 players to explore its open world environment and engage in cooperative or competitive game matches. The game features a range of technical and graphical improvements across the entire experience including performance enhancements for select vehicles in GTA Online, and so much more.', 'https://www.igdb.com/games/grand-theft-auto-online', '["Xbox Series X|S", "PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox 360", "Xbox One"]', NULL, 8.6, 0, 2.44, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
