VALUES (NULL, NULL, 3199, 'Dead Rising 3', 'Dead Rising 3', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pvc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a6wqz2s1cm7qoc63btj6.jpg', 'Available exclusively for Xbox One and Windows, Dead Rising 3 marks the return of one of the most popular zombie video game franchises. Set 10 years after the events of Fortune City in Dead Rising 2, players are introduced to Nick Ramos, a young mechanic with a strange tattoo and a mysterious past, who must find a way to escape a city full of zombies before an impending military strike wipes the city of Los Perdidos, California, and everyone in it, off the map. Nick can’t do it alone – he must join up with other survivors to stay alive. They must fight their way out before it’s too late.', 'https://www.igdb.com/games/dead-rising-3', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 7.2, 0, 1.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
