VALUES (NULL, NULL, 1905, 'Fortnite', 'Fortnite', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocxbi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6aet.jpg', 'Fortnite is a free-to-play online game where you and your friends can create, play and battle. Be the last player standing in Battle Royale and Zero Build, experience a concert or live event, or discover over a million creator-made games, including racing, parkour, zombie survival and more.', 'https://www.igdb.com/games/fortnite', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
