VALUES (NULL, NULL, 262530, 'Killing Floor III', 'Killing Floor III', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9f9j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2gx8.jpg', 'It''s 2091. Megacorporation Horzine has produced the ultimate army: an obedient horde of bioengineered monstrosities called "Zeds." Now, only the rebel group Nightfall stands between these infernal creations and the future of humanity.', 'https://www.igdb.com/games/killing-floor-iii', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.7, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
