VALUES (NULL, NULL, 393398, 'Librarian: Tidy Up the Arcane Library!', 'Librarian: Tidy Up the Arcane Library!', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobotz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hml.jpg', 'Librarian: Tidy Up the Arcane Library! is a single-player simulation. You need return scattered books to proper places in an Arcane Library. As completed rows of bookshelves, you can learn ability to improve your efficiency. Use your skills and strategies to shelve 3,072 books as quick as you can.', 'https://www.igdb.com/games/librarian-tidy-up-the-arcane-library', '["PC (Microsoft Windows)"]', NULL, 7.3, 0, 2.06, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
