VALUES (NULL, NULL, 119994, 'Waltz of the Wizard', 'Waltz of the Wizard', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coautq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4p97.jpg', 'Delve into a meticulously crafted fantasy world, greatly expanded with major updates since the original release and now includes an all new Screen Mode! Waltz of the Wizard includes hours of rich fantasy content, cutting-edge VR features and many curious secrets. Experience magical powers in a world inspired classical fantasy fiction! Combine arcane ingredients into a boiling cauldron with the help of an ancient talking skull, unleashing spells upon a fully interactive and mysterious world. Use blazingly fast voice interactions to wield magic, talk to characters or team up with a friend in local co-op on a screen with controller/keyboard and a VR headset.', 'https://www.igdb.com/games/waltz-of-the-wizard--1', '["Meta Quest 2", "PlayStation VR2", "PlayStation VR", "PC (Microsoft Windows)", "Meta Quest 3"]', NULL, 7.1, 0, 1.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
