VALUES (NULL, NULL, 342686, 'Alchemy Factory', 'Alchemy Factory', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rna.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3kpq.jpg', '"Alchemy Factory" is a first-person factory building & shop simulation game. You''ll process raw materials, research new recipes, and build fully automated production lines to craft and sell a wide range of alchemical products.', 'https://www.igdb.com/games/alchemy-factory', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
