VALUES (NULL, NULL, 16999, 'Conan Exiles', 'Conan Exiles', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa90l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tbenllfh4mpgsmhyzbm9.jpg', 'Conan Exiles is an online multiplayer survival game set in the lands of Conan the Barbarian. Enter a vast, open-world sandbox and play together with friends and strangers as you build your own home or even a shared city. Survive freezing cold temperatures, explore loot-filled dungeons, develop your character from a lowly peasant to a mighty barbarian, and fight to dominate your enemies in epic siege wars.
Conan Exiles can be played in full single-player, co-op, or persistent online multiplayer.', 'https://www.igdb.com/games/conan-exiles', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.1, 0, 1.34, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
