VALUES (NULL, NULL, 125633, 'Crimson Desert Enhanced', 'Crimson Desert Enhanced', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocyjx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57ol.jpg', 'Crimson Desert is an open-world action-adventure game set in the beautiful yet brutal continent of Pywel. Embark on a journey as the Greymane Kliff and restore what has been lost. Explore uncharted lands, fight against threats that stand in your way, and discover the wonders the world has in store.', 'https://www.igdb.com/games/crimson-desert-enhanced--1', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 8.6, 0, 2.015, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
