INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 20752, 'Heretic II', 'Heretic II', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29sq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xodo47sorcqtgtoaezpx.jpg', 'Heretic II is a third-person action game based on the Quake II engine that plunges you into a deep, compelling game combining brutal face-to-face combat and mystery-laden adventure. Gamers travel through complex, richly detailed environments filled with stunning special effects, wicked magic spells, detailed characters, vivid artwork and challenging level designs created by the Raven team and renowned fantasy artist Brom.', 'https://www.igdb.com/games/heretic-ii', '["Linux", "PC (Microsoft Windows)", "Mac", "Amiga"]', NULL, 7.7, 0, 1.05, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
