VALUES (NULL, NULL, 8687, 'Witchaven', 'Witchaven', 'game', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2y4v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arybw.jpg', 'Witchaven is a medieval fantasy first-person shooter video game with action role-playing game elements. Its sword and sorcery style story tasks the knight Grondoval with a quest to seek out and kill a powerful evil witch in her titular fortress.', 'https://www.igdb.com/games/witchaven', '["PC (Microsoft Windows)", "DOS"]', NULL, NULL, 0, 1.05, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
