VALUES (NULL, NULL, 333600, 'Blades of Fire', 'Blades of Fire', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gvk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3c98.jpg', 'Introducing Blades of Fire, an all-new action adventure that takes you across a beautiful world full of uncertainty and challenge. You take on the role of Aran de Lira, firstborn of the King’s Ward. The newly crowned Queen Nerea has cast a powerful spell that turns steel into stone and only her arms of abominations wield the divine metal against which other blades shatter…', 'https://www.igdb.com/games/blades-of-fire', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.7, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
