VALUES (NULL, NULL, 1270, 'Darksiders', 'Darksiders', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29t0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wpui1ov2j61ymbjxleb2.jpg', 'Apocalyptic power of War: Unleash the wrath of War, combining brutal attacks and supernatural abilities to decimate all who stand in your way.
Epic quest: Battle across the wastelands and demon-infested dungeons of the decimated Earth in your quest for vengeance and redemption.
Character progression: Uncover powerful ancient relics, upgrade your weapons, unlock new abilities, and customize your gameplay style.
Battle Heaven and Hell: Battle against all who stand in your way—from war-weary angelic forces to Hell''s hideous demon hordes.', 'https://www.igdb.com/games/darksiders', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.0, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
