VALUES (NULL, NULL, 13898, 'Lucky & Wild', 'Lucky & Wild', 'game', 1992, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ftf3upvbpaocs1cg55od.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc162is.jpg', 'The object of the game is to stop a bunch of criminals led by the main antagonist Big Cigar from breaking laws. The plot of the game is to stop a bunch of drug dealers. The game stars 2 men. "Wild" (based on "Hutch" and "Cash"), a surfer with long blonde hair. who is the shooter. And "Lucky" (modeled after "Starsky" and "Tango"), is the driver and wields a gun.', 'https://www.igdb.com/games/lucky-and-wild', '["Arcade"]', NULL, NULL, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
