VALUES (NULL, NULL, 2738, 'LEGO Batman: The Videogame', 'LEGO Batman: The Videogame', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10cu.jpg', 'The fun of LEGO, the drama of Batman and the uniqueness of the combination makes for a comical and exciting adventure in LEGO Batman: The Videogame. Play as Batman and his sidekick Robin as you build, drive, swing and fight your way through Gotham City capturing escaped villains including The Joker, Penguin, Scarecrow and more. Then, jump into the story from the other side and play as Batman''s foes! Enjoy the power you wield and battle Batman while spreading chaos throughout the city. There is no rest for the good (or evil!).', 'https://www.igdb.com/games/lego-batman-the-videogame', '["PlayStation 3", "Wii", "PC (Microsoft Windows)", "Mac", "PlayStation Portable", "Xbox 360", "PlayStation 2"]', NULL, 7.5, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
