VALUES (NULL, NULL, 543, 'Call of Juarez: The Cartel', 'Call of Juarez: The Cartel', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uuf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1du4.jpg', 'Embark on a bloody journey from Los Angeles to Juarez as lawlessness of the Old West is brought to the present. Welcome to the new Wild West.', 'https://www.igdb.com/games/call-of-juarez-the-cartel', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 5.2, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
