VALUES (NULL, NULL, 252502, 'Baby Steps', 'Baby Steps', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6llb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2cfl.jpg', 'Play as Nate, an unemployed failson with nothing going for him, until one day he discovers a power he never knew he had… putting one foot in front of the other. Explore a world shrouded in mist, one step at a time. Hike the serene mountains by placing each footstep yourself, in original physics-based gameplay from the minds behind Ape Out and Getting Over It. Take in the sights, fall in love with the local fauna, and try to find meaning in a wasted life.', 'https://www.igdb.com/games/baby-steps', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.2, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
