VALUES (NULL, NULL, 116753, 'A Short Hike', 'A Short Hike', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6e83.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar58k0.jpg', 'A Short Hike is an exploration adventure game set in Hawk Peak Provincial Park. Players control Claire, a young bird who sets out to reach the summit of Hawk Peak while waiting for an important phone call.

The game allows players to climb, glide and explore the park at their own pace, meeting other visitors, completing small tasks and collecting items that improve Claire’s movement.', 'https://www.igdb.com/games/a-short-hike', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.5, 0, 1.1, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
