VALUES (NULL, NULL, 262534, 'Expeditions: A MudRunner Game', 'Expeditions: A MudRunner Game', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ywx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2hl9.jpg', 'Embark on scientific expeditions with this new off-road adventure from the creators of MudRunner and SnowRunner. Lead research missions as you drive a variety of all-terrain vehicles, using high-tech tools and managing your camp and crew to ensure your success in the wild.', 'https://www.igdb.com/games/expeditions-a-mudrunner-game', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.2, 0, 1.08, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
