VALUES (NULL, NULL, 143574, 'Planet Crafter', 'Planet Crafter', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocjqh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6r3n.jpg', 'You are sent on an hostile planet with one mission: Make it habitable for Humans. You''ll have to survive, collect ressources, build your base and machines in order to heat the planet, create an atmosphere with oxygen and eventually geo-engineer an entire planet.', 'https://www.igdb.com/games/planet-crafter', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.4, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
