VALUES (NULL, NULL, 118218, 'Tom Clancy''s Ghost Recon: Breakpoint', 'Tom Clancy''s Ghost Recon: Breakpoint', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocogs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ie.jpg', 'Tom Clancy''s Ghost Recon Breakpoint is a military shooter set in a diverse and hostile open world entirely playable solo or in up to four-player co-op. Players will discover Auroa, a mysterious island where the most technically advanced facilities meet wild and untamed nature. Home to drone creators, tech giant Skell Technology, Auroa has fallen into the wrong hands and all contact has been lost.', 'https://www.igdb.com/games/tom-clancys-ghost-recon-breakpoint', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 5.9, 0, 1.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
