VALUES (NULL, NULL, 13205, 'Astroneer', 'Astroneer', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobyfe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4lmc.jpg', 'Interact with strange new worlds in a unique and tactile way, molding the environment itself as if it were clay in your hands. Build your base, master resource management, automate your production lines, and more as you unravel the mysteries of the universe, alone or with friends.', 'https://www.igdb.com/games/astroneer', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
