VALUES (NULL, NULL, 89326, 'Breathedge', 'Breathedge', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wvo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7uw.jpg', 'Survive in outer space! Together with your immortal chicken, discover the truth behind your sudden spaceship crash. Craft tools, pilot vehicles, and even control space stations to survive and explore the wreckage.', 'https://www.igdb.com/games/breathedge', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.6, 0, 1.16, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
