VALUES (NULL, NULL, 214394, 'Dune: Awakening', 'Dune: Awakening', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobf3a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3n2m.jpg', 'Dune: Awakening is an open-world survival game set on the desert planet Arrakis. Players create a custom character and must manage thirst, maintain stillsuits, and contend with environmental hazards like sandstorms, extreme heat, and roaming sandworms. The game involves scavenging resources, crafting equipment, building shelters, and competing with other players to harvest and transport spice. As players progress, they advance through phases from basic survival to leading a guild, eventually participating in faction warfare between House Atreides and House Harkonnen. The game features single-player, and multiplayer which can be fully played in PvE with dedicated PvP zones.', 'https://www.igdb.com/games/dune-awakening', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.9, 0, 1.05, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
