VALUES (NULL, NULL, 130216, 'Hardspace: Shipbreaker', 'Hardspace: Shipbreaker', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2m8b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6ne.jpg', 'Welcome to LYNX, the galaxy’s leading ship-salvaging corporation! Across your career, you’ll have the privilege of paying your debt to us by purchasing salvaging rights to increasingly large and valuable ships. Cut them open and extract as much value as possible!', 'https://www.igdb.com/games/hardspace-shipbreaker', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.9, 0, 1.08, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
