VALUES (NULL, NULL, 5574, '7 Days to Die', '7 Days to Die', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5l6.jpg', 'Set in a brutally unforgiving post-apocalyptic world overrun by the undead, 7 Days to Die is an open-world game that is a unique combination of first person shooter, survival horror, tower defense, and role-playing games. It presents combat, crafting, looting, mining, exploration, and character growth, in a way that has seen a rapturous response from fans worldwide. Play the definitive zombie survival sandbox RPG that came first. Navezgane awaits!', 'https://www.igdb.com/games/7-days-to-die', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 5.3, 0, 1.05, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
