VALUES (NULL, NULL, 17011, 'Subterrain', 'Subterrain', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24un.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11t0.jpg', 'Subterrain is uncompromising Sci-Fi survival on Mars! Manage the entire colony single-handed! Craft, Research, Explore and Fight against evolving mutants. Vast open world and randomly generated levels to explore! Can you survive long enough to escape the horror?', 'https://www.igdb.com/games/subterrain', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 6.8, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
