VALUES (NULL, NULL, 151902, 'Carrier Command 2', 'Carrier Command 2', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nbi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzfy.jpg', 'Carrier Command 2 is Strategy, Planning and Teamwork on a scale that is both engaging and manageable. True to MicroProse''s heritage and the debut title of the development company Geometa , Carrier Command 2 is all about meaningful decisions.', 'https://www.igdb.com/games/carrier-command-2', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, NULL, 0, 9.79, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
