VALUES (NULL, NULL, 14314, 'TerraTech', 'TerraTech', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coalaw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4c1d.jpg', 'As a prospector starting out on a procedurally generated exo-planet, TerraTech is a galactic exploration game where you need to build an empire from the ground up. Design your own fleet of unique vehicles and take them into battle, and you shape your journey the way you want to, researching the technologies you want and allying yourself with various corporations to create a burgeoning fleet in the lawless frontier of space.', 'https://www.igdb.com/games/terratech', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.5, 0, 9.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
