VALUES (NULL, NULL, 26473, 'SimplePlanes', 'SimplePlanes', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co414r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sjv.jpg', 'Build airplanes by snapping parts together, designing wing sections, and attaching engines. At any time, you can strap yourself into the cockpit and see how it flies with realistic physics. If you''re not in the mood for building, over 100,000 airplanes are available to download for free.', 'https://www.igdb.com/games/simpleplanes', '["Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 8.0, 0, 8.56, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
