VALUES (NULL, NULL, 307368, 'PVKK: Planetenverteidigungskanonenkommandant', 'PVKK: Planetenverteidigungskanonenkommandant', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8fj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar34mw.jpg', 'Operate your planetary defense cannon to fend off an interplanetary invasion from the comfort of your cozy bunker. You’re here to stay, so obey your superiors, press the right buttons, and sip your daily tea ration - it''s good for you.', 'https://www.igdb.com/games/pvkk-planetenverteidigungskanonenkommandant', '["PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 8.09, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
