VALUES (NULL, NULL, 228531, 'Immortals of Aveum', 'Immortals of Aveum', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dtk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar29qj.jpg', 'From the creative director of Dead Space and multiple Call of Duty campaigns comes Immortals of Aveum, a single-player first-person magic shooter set in an original fantasy universe engulfed in magic, rife with conflict, and on the verge of oblivion.', 'https://www.igdb.com/games/immortals-of-aveum', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.1, 0, 9.29, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
