VALUES (NULL, NULL, 11800, 'Divinity: Original Sin II', 'Divinity: Original Sin II', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y5v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4h4.jpg', 'Divinity: Original Sin II is a single- and multiplayer top-down, party-based role-playing game with pen & paper RPG-like levels of freedom. It features turn-based combat, a strong focus on systematic gameplay and a well-grounded narrative.', 'https://www.igdb.com/games/divinity-original-sin-ii', '["PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 8.9, 0, 9.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
