VALUES (NULL, NULL, 23719, 'Neverwinter Nights: Enhanced Edition', 'Neverwinter Nights: Enhanced Edition', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ndm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9qq.jpg', 'Neverwinter Nights: Enhanced Edition is an updated version of the 2002 video game Neverwinter Nights. The Enhanced Edition is based on Neverwinter Nights: Diamond Edition and it comes with the base game as well as the Shadows of Undrentide, Hordes of the Underdark, Kingmaker, Witch''s Wake and ShadowGuard expansions. Remastered version brings numerous technological improvements to the game, including an updated graphics engine and revitalized multiplayer support.', 'https://www.igdb.com/games/neverwinter-nights-enhanced-edition', '["PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 5.5, 0, 9.53, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
