INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 214, 'Neverwinter Nights 2', 'Neverwinter Nights 2', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1syd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mzpcevfbmyoolpifggyz.jpg', 'Neverwinter Nights 2 (NWN2) is a computer role-playing game set in the fantasy world of the Forgotten Realms, one of the popular campaign settings of Dungeons and Dragons. It takes the player from the tiniest of villages into a sweeping tale of danger and war, chronicling their rise from a peasant to a full-fledged hero of the Realms, defending it against one of the greatest threats of the age.

Build a character that suits your style of play - good or evil, chaotic or lawful, with any number of skills, feats and professions available at the click of a button. Whether lobbing fireballs and researching forgotten spells as a powerful Wizard, hacking a trail through legions of orcs as a Fighter armed only with a battle axe and your courage, or taking on the role of a Rogue that can slip into the shadows at a moment''s notice and take the purse from even the most perceptive of guardsmen. Choose your alignment, your allies, your companions, and how you want your character to develop... design the character you want, role-play the way you want, and carry the battle to the enemy.

The design aspects of Neverwinter Nights 2 don''t stop there, however. Past the campaign included with the game itself, Neverwinter Nights 2 also gives you all the tools you need to build your own modules, campaigns, and adventures for your friends - move buildings, terrain, script encounters, write dialogues, create quests and items - everything you need to create an epic adventure of your own is included in the toolset for you and any other worldbuilder to use.', 'https://www.igdb.com/games/neverwinter-nights-2', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.4, 0, 9.53, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
