VALUES (NULL, NULL, 83, 'Baldur''s Gate: Dark Alliance', 'Baldur''s Gate: Dark Alliance', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tay.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8p8.jpg', 'Baldur’s Gate: Dark Alliance is a revolutionary action adventure with an epic tale of intrigue, fierce alliances, explosive spell effects and highly detailed creatures and environments. Baldur’s Gate: Dark Alliance is a benchmark of technology and gameplay.', 'https://www.igdb.com/games/baldur-s-gate-dark-alliance', '["Xbox", "PlayStation 4", "Nintendo GameCube", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch", "PlayStation 2"]', NULL, 8.3, 0, 8.54, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
