VALUES (NULL, NULL, 117170, 'Stellar Blade', 'Stellar Blade', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9s0t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3t1d.jpg', 'Stellar Blade is a third-person action-adventure game set on a post-apocalyptic Earth. Players control Eve, an elite soldier deployed from an orbital colony to reclaim the planet from hostile creatures called Naytibas. The combat system emphasizes timing-based parrying and evasion, with skill gauges that unlock powerful attacks and buffs. The game features exploration across ruined environments, side quests from NPC survivors in the last human city of Xion, and a narrative with multiple endings based on player choices.', 'https://www.igdb.com/games/stellar-blade', '["Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.4, 0, 10.02, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
