VALUES (NULL, NULL, 134606, 'Demon''s Souls', 'Demon''s Souls', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7dh.jpg', 'Entirely rebuilt from the ground up and masterfully enhanced, Demon''s Souls is a remake of the 2009 release that introduces the horrors of a fog-laden, dark fantasy land to a whole new generation of gamers. Those who’ve faced its trials and tribulations before, can once again challenge the darkness in stunning visual quality with incredible performance. The remake features improved graphics and animations, sound and lighting tweaks and a reimagining of many of the visual, musical and mechanical aspects of the original game.', 'https://www.igdb.com/games/demons-souls', '["PlayStation 5"]', NULL, 8.9, 0, 9.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
