VALUES (NULL, NULL, 117297, 'Aion 2', 'Aion 2', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod0sw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6mdj.jpg', 'Aion 2 is the only MMORPG built around a world where the sky is the battlefield. Choose your faction, ascend as a Daeva, and fight a faction war across a world 36 times larger than the original.', 'https://www.igdb.com/games/aion-2', '["Android", "PC (Microsoft Windows)", "iOS"]', NULL, 8.9, 0, 0.0, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
