VALUES (NULL, NULL, 228539, 'Banishers: Ghosts of New Eden', 'Banishers: Ghosts of New Eden', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6lmo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2hre.jpg', 'Hunt ghosts as two memorable characters in a story-driven Action-RPG where your decisions carry dramatic consequences. Torn between honoring your oath to the living and saving your departed partner, how far will you go for love?', 'https://www.igdb.com/games/banishers-ghosts-of-new-eden', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
