VALUES (NULL, NULL, 329, 'Dungeon Siege', 'Dungeon Siege', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2348.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6n3s.jpg', 'Dungeon Siege combines the immersive elements of a role-playing game with over-the-top intensity and non-stop action. Dungeon Siege plunges you into a continuous 3D fantasy world where you face off against an army of evil that has been unleashed.', 'https://www.igdb.com/games/dungeon-siege', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.5, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
