VALUES (NULL, NULL, 753, 'Icewind Dale', 'Icewind Dale', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1t8h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jcugijw0ikzhiypycv5x.jpg', 'In the northernmost reaches of the Forgotten Realms lies a frozen and untamed region known as Icewind Dale. Journey deep into the Spines of the World mountains, a harsh and unforgiving territory teeming with fearsome and merciless beasts. There you must confront an ancient evil that threatens to unleash an unspeakable horror upon the face of Faerûn.', 'https://www.igdb.com/games/icewind-dale', '["PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 8.5, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
