VALUES (NULL, NULL, 972, 'Resident Evil Outbreak', 'Resident Evil Outbreak', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w5p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scievm.jpg', 'Resident Evil Outbreak is a survival-horror game released exclusively for the PlayStation 2. The gameplay is similar to the previous Resident Evil games and consists mainly of exploring, solving puzzles, finding items and surviving. It was the first Resident Evil game with multiplayer capability, using the PlayStation 2''s online network. Up to four players could participate simultaneously in one scenario. Alternately, in single-player mode, the player is accompanied by two AI-controlled characters.', 'https://www.igdb.com/games/resident-evil-outbreak', '["PlayStation 2"]', NULL, 6.8, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
