VALUES (NULL, NULL, 1009, 'The Last of Us', 'The Last of Us', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m4a.jpg', 'The Last of Us is a third-person action-adventure game featuring a mix of exploration, stealth and combat. Players face both infected creatures and hostile human enemies while progressing through varied environments. The game includes a narrative-driven single-player campaign and a competitive online multiplayer mode called Factions. Trophy support is included, and additional downloadable content was made available separately.', 'https://www.igdb.com/games/the-last-of-us', '["PlayStation 3"]', NULL, 9.2, 0, 1.07, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
