VALUES (NULL, NULL, 36813, 'The Evil Within 2', 'The Evil Within 2', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wgu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/avqjxxgafguhy8gk7rqp.jpg', 'The Evil Within 2 is the latest evolution of survival horror. Detective Sebastian Castellanos has lost it all. But when given a chance to save his daughter, he must descend once more into the nightmarish world of STEM.

Horrifying threats emerge from every corner as the world twists and warps around him. Will Sebastian face adversity head on with weapons and traps, or sneak through the shadows to survive.', 'https://www.igdb.com/games/the-evil-within-2', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 8.2, 0, 1.09, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
