VALUES (NULL, NULL, 880, 'Resident Evil 2', 'Resident Evil 2', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vz0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/amlyvf6ngy3sgzmgz9kw.jpg', 'Resident Evil 2 is a sequel to the first Resident Evil title. Like the previous game in the series, Resident Evil 2 is a 3D action-adventure using three-dimensional polygon characters over two-dimensional pre-rendered backgrounds, with the action viewed through a variety of cinematic fixed camera angles in each room. Players can choose to play as one of two possible characters; each goes through the same initial scenario but with differences in the type of weaponry they find and the people they meet along the way.', 'https://www.igdb.com/games/resident-evil-2', '["PlayStation 3", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation", "PlayStation Portable", "Dreamcast"]', NULL, 6.9, 0, 1.42, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
