VALUES (NULL, NULL, 228258, 'Amnesia: The Bunker', 'Amnesia: The Bunker', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5us3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar227b.jpg', 'Amnesia: The Bunker is a first-person horror game set in a desolate WW1 Bunker. Face the oppressing terrors stalking the dark corridors. Search for and use the tools and weapons at your disposal, while keeping the lights on at all costs. Overcome fear, persevere, and make your way out alive.', 'https://www.igdb.com/games/amnesia-the-bunker', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.9, 0, 1.04, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
