VALUES (NULL, NULL, 71, 'Portal', 'Portal', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coay61.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5e0u.jpg', 'Waking up in a seemingly empty laboratory, the player is made to complete various physics-based puzzle challenges through numerous test chambers in order to test out the new Aperture Science Handheld Portal Device, without an explanation as to how, why or by whom.', 'https://www.igdb.com/games/portal', '["PlayStation 3", "Linux", "Android", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Nintendo Switch"]', NULL, 8.3, 0, 1.03, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
