VALUES (NULL, NULL, 16310, 'Infra', 'Infra', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qez.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arr7o.jpg', 'Infra is an atmospheric and completely non-violent first-person puzzle/adventure that deals with the issues of deteriorating infrastructure. The player controls an ordinary structural analyst through abandoned factories, forgotten tunnels and unsafe buildings in a dangerous, crumbling industrial city and its surrounding rural areas. Along the way, the player will be taking photos of structural weaknesses, solving environmental puzzles and unravelling a thought-provoking story centered around corruption and deception.', 'https://www.igdb.com/games/infra', '["PC (Microsoft Windows)"]', NULL, 6.7, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
