VALUES (NULL, NULL, 106847, 'Coffee Talk', 'Coffee Talk', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55rx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4tdt.jpg', 'Coffee Talk is a coffee brewing and heart-to-heart talking simulator about listening to fantasy-inspired modern peoples’ problems, and helping them by serving up a warm drink or two.', 'https://www.igdb.com/games/coffee-talk', '["PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.1, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
