VALUES (NULL, NULL, 194506, 'Stray Gods: The Roleplaying Musical', 'Stray Gods: The Roleplaying Musical', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kld.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1r6t.jpg', 'Murder. Gods. Romance. Band practice? Unravel the mystery of the Last Muse’s death in an interactive roleplaying musical where Greek gods live hidden among us. Use your newfound powers of musical persuasion to choose how this wry and moving saga will unfold. How will the curtain fall?', 'https://www.igdb.com/games/stray-gods-the-roleplaying-musical', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 1.01, '2026-11-21 21:29:28', '2026-11-21 21:29:28')
