VALUES (NULL, NULL, 1911, 'Path of Exile', 'Path of Exile', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1n6w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjpc.jpg', 'You are an Exile, struggling to survive on the dark continent of Wraeclast, as you fight to earn power that will allow you to exact your revenge against those who wronged you. Created by hardcore gamers, Path of Exile is an online Action RPG set in a dark fantasy world.', 'https://www.igdb.com/games/path-of-exile', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.0, 0, 7.03333333333333321e+00, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
