VALUES (NULL, NULL, 30225, 'Kenshi', 'Kenshi', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coclf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4l5.jpg', 'A free-roaming squad based RPG. Focusing on open-ended sandbox gameplay features rather than a linear story. Be a trader, a thief, a rebel, a warlord, an adventurer, a farmer, a slave, or just food for the cannibals. Research new equipment and craft new gear. Purchase and upgrade your own buildings to use as safe fortified havens when things go bad, or use them to start up a business. Aid or oppose the various factions in the world while striving for the strength and wealth necessary to simply survive in the harsh desert. Train your men up from puny victims to master warriors. Carry your wounded squad mates to safety and get them all home alive.', 'https://www.igdb.com/games/kenshi', '["PC (Microsoft Windows)"]', NULL, 8.4, 0, 7.7175, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
