VALUES (NULL, NULL, 129596, 'Cyber Knights: Flashpoint', 'Cyber Knights: Flashpoint', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75jd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3pat.jpg', 'Cyber Knights is a tactical RPG in an original cyberpunk setting ten years in the making. Build your team of hackers, mercs and malcontents wisely; their stories will become interwoven with your own. Use powerful cyberware, shady connections, stealth, hacking and more to rise in the neon-soaked future.', 'https://www.igdb.com/games/cyber-knights-flashpoint', '["Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, NULL, 0, 6.285, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
