VALUES (NULL, NULL, 19564, 'Death Stranding', 'Death Stranding', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocsvh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fq9mae2ruszujzbybiif.jpg', 'Death Stranding is an action game set in a post-apocalyptic United States.

Players control Sam Porter Bridges, a courier tasked with reconnecting isolated cities via a communication network while delivering essential cargo. The gameplay blends traversal, resource management, and narrative elements, with a focus on social connectivity through asynchronous multiplayer. It is known for its unique mechanics, atmospheric world, and philosophical themes.', 'https://www.igdb.com/games/death-stranding', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 8.5, 0, 9.78000000000000113e+00, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
