VALUES (NULL, NULL, 27082, 'Raft', 'Raft', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xdc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardgp.jpg', 'Raft throws you and your friends into an epic oceanic adventure! Alone or together, players battle to survive a perilous voyage across a vast sea! Gather debris, scavenge reefs and build your own floating home, but be wary of the man-eating sharks!', 'https://www.igdb.com/games/raft', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 5.27999999999999936e+00, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
