VALUES (NULL, NULL, 19520, 'Far: Lone Sails', 'Far: Lone Sails', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa36a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hh.jpg', 'Far: Lone Sails is a vehicle adventure game. The player needs to maintain and upgrade their unique vessel to traverse a dried-out sea, with the remains of a decaying civilization scattered out on the seabed. Keep your unique vessel going, overcome numerous obstacles and withstand the hazardous weather conditions.', 'https://www.igdb.com/games/far-lone-sails', '["PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 5.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
