VALUES (NULL, NULL, 11208, 'NieR:Automata', 'NieR:Automata', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5pcj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4n6u.jpg', 'NieR: Automata tells the story of androids 2B, 9S and A2 and their battle to reclaim the machine-driven dystopia overrun by powerful machines.', 'https://www.igdb.com/games/nier-automata', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 8.8, 0, 1.15233333333333334e+01, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
