VALUES (NULL, NULL, 125642, 'Path of Exile 2', 'Path of Exile 2', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ae0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5gc9.jpg', 'Path of Exile 2 is a next generation Action RPG created by Grinding Gear Games. Set years after the original Path of Exile, you will return to the dark world of Wraeclast and seek to end the corruption that is spreading. Path of Exile 2 is a free-to-play online multiplayer game with co-op for up to six players.', 'https://www.igdb.com/games/path-of-exile-2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 8.8, 0, 5.535, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
