VALUES (NULL, NULL, 35282, 'CrossCode', 'CrossCode', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28wy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar68tt.jpg', 'A retro-inspired 2D Action RPG set in the distant future. CrossCode combines 16-bit SNES-style graphics with butter-smooth physics, a fast-paced combat system, and engaging puzzle mechanics, served with a gripping sci-fi story.', 'https://www.igdb.com/games/crosscode', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.5, 0, 10.29, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
