VALUES (NULL, NULL, 252837, 'Still Wakes the Deep', 'Still Wakes the Deep', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8dbd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2cjz.jpg', '1975. Disaster strikes the Beira D oil rig off the coast of Scotland. Navigate the collapsing rig to save your crew from an otherworldly horror on the edge of all logic and reality.', 'https://www.igdb.com/games/still-wakes-the-deep', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 3.1, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
