VALUES (NULL, NULL, 2117, 'DayZ', 'DayZ', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaqs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar74t.jpg', 'DayZ is a hardcore open-world survival game with only one rule: stay alive, no matter what. How long can you survive a post-apocalyptic world? A land overrun with an infected "zombie" population, where you compete with other survivors for limited resources. Will you team up with strangers and stay strong together? Or play as a lone wolf to avoid betrayal? This is DayZ, this is your story.', 'https://www.igdb.com/games/dayz', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.0, 0, 1.03266666666666679e+01, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
