VALUES (NULL, NULL, 123, 'World of Warcraft', 'World of Warcraft', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l7z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar583d.jpg', 'World of Warcraft is a massively multiplayer online roleplaying game (MMORPG) set in the Warcraft universe. Players assume the roles of Warcraft heroes as they explore, adventure, and quest across a vast world. Being "Massively Multiplayer," World of Warcraft allows thousands of players to interact within the same world. Whether adventuring together or fighting against each other in epic battles, players will form friendships, forge alliances, and compete with enemies for power and glory.', 'https://www.igdb.com/games/world-of-warcraft', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.5, 0, 7.765, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
