VALUES (NULL, NULL, 219126, 'Abiotic Factor', 'Abiotic Factor', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co85d2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vpq.jpg', 'Abiotic Factor is a survival crafting experience for 1-6 players set in the depths of an underground research facility. Caught between paranormal containment failure, a military crusade, and chaos from a dozen realms, the world’s greatest minds must survive against the universe’s biggest threats.', 'https://www.igdb.com/games/abiotic-factor', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 7.7125, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
