VALUES (NULL, NULL, 911, 'Tom Clancy''s Splinter Cell: Chaos Theory', 'Tom Clancy''s Splinter Cell: Chaos Theory', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coamhg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar79c.jpg', 'You are Sam Fisher, the NSA''s most elite black-ops agent. To achieve your mission you will kill from close range, attack with your combat knife, shoot with the prototype Land Warrior rifle, and use radical suppression techniques such as the inverted neck break. Also take on cooperative multiplayer infiltration missions, where teamwork is the ultimate weapon.', 'https://www.igdb.com/games/tom-clancy-s-splinter-cell-chaos-theory', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 8.1, 0, 2.03, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
