VALUES (NULL, NULL, 279661, 'Monster Hunter Wilds', 'Monster Hunter Wilds', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co904o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2q59.jpg', 'The unbridled force of nature runs wild and relentless, with environments transforming drastically from one moment to the next. This is a story of monsters and humans and their struggles to live in harmony in a world of duality.', 'https://www.igdb.com/games/monster-hunter-wilds', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.5, 0, 6.535, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
