VALUES (NULL, NULL, 112874, 'Horizon Forbidden West', 'Horizon Forbidden West', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gvu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cwx.jpg', 'Horizon Forbidden West continues Aloy’s story as she moves west to a far-future America to brave a majestic, but dangerous frontier where she’ll face awe-inspiring machines and mysterious new threats.', 'https://www.igdb.com/games/horizon-forbidden-west', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.9, 0, 2.035, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
