VALUES (NULL, NULL, 215036, 'Infection Free Zone', 'Infection Free Zone', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55h7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1uiq.jpg', 'Take charge of a group of survivors from your city. Choose your base of operations, then rebuild and readapt the buildings around you to create a self-sustaining settlement. And when the night falls - Defend the zone from the infected! Play on any city in the world, using real geographical data!', 'https://www.igdb.com/games/infection-free-zone', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 2.05, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
