VALUES (NULL, NULL, 157439, 'HighFleet', 'HighFleet', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co42g9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwyh.jpg', 'Battle for survival in the skies of a mysterious future Earth in this unique action-strategy game mixing arcade combat, exploration, management and diplomacy. As giant flying ships wage spectacular aerial warfare, a prophecy tells of one who will save the world – could it be you?', 'https://www.igdb.com/games/highfleet', '["PC (Microsoft Windows)"]', NULL, 7.4, 0, 6.31666666666666643e+00, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
