VALUES (NULL, NULL, 6748, 'Killing Floor 2', 'Killing Floor 2', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2coc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar75e.jpg', 'In Killing Floor 2 players descend into Europe where the Zed outbreak has quickly spread and gained unstoppable momentum. Just one month after the conclusion of the events in the original Killing Floor, the clones are everywhere and civilization is in disarray; governments have collapsed, and military forces are gone.', 'https://www.igdb.com/games/killing-floor-2', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.7, 0, 2.02, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
