VALUES (NULL, NULL, 536, 'Dead Island', 'Dead Island', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lym.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vw3w5kjrbnaf4c0owrpx.jpg', 'The player is drawn into the world of Dead Island on the brink of a mysterious epidemic that suddenly, and without warning, breaks out on the fictional island of Banoi. As a guest of the Royal Palms Resort, the player''s stay was supposed to be a dream holiday; a luxurious getaway to the beautiful beaches of a tropical paradise. But faced with the reality of a zombie apocalypse, there is only one thing left to do: Survive. This is Dead Island; a paradise to die for.', 'https://www.igdb.com/games/dead-island', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.1, 0, 3.05, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
