VALUES (NULL, NULL, 55163, 'Resident Evil Village', 'Resident Evil Village', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab9q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar82j.jpg', 'Resident Evil Village is a first-person survival horror game and the sequel to Resident Evil 7: Biohazard. The game maintains elements from previous Resident Evil games, with players having to scavenge environments for items and manage their resources. However, it adds more action-oriented gameplay, with higher enemy counts and a greater emphasis on combat.', 'https://www.igdb.com/games/resident-evil-village', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.5, 0, 2.055, '2026-11-19 20:56:22', '2026-11-21 21:29:28')
