VALUES (NULL, NULL, 201789, 'Arma Reforger', 'Arma Reforger', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa97g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zk9.jpg', 'Powered by the new Enfusion engine, Arma Reforger lets you fight for supremacy over 51 km2 of incredible island terrain in an authentic Cold War setting, or create unique scenarios in real-time with the Game Master curation mode. Return to Everon, the war-driven microstate from the hit game that started it all, Arma: Cold War Assault.', 'https://www.igdb.com/games/arma-reforger', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 10.4, '2026-11-20 01:06:03', '2026-11-21 21:29:28')
